-- EDP Slice C (BI-PF-1415): make derived views respect the CALLER's RLS.
-- PG views default to owner rights (our owner is superuser -> would bypass RLS). security_invoker
-- makes each view evaluate RLS as the invoking role.

DROP VIEW IF EXISTS v_agents_live;
CREATE VIEW v_agents_live WITH (security_invoker = true) AS SELECT id, tenant_id, project_id, run_id, payload, computed_at FROM derived_outputs WHERE kind = 'agents-live.json';
DROP VIEW IF EXISTS v_analysis_report;
CREATE VIEW v_analysis_report WITH (security_invoker = true) AS SELECT id, tenant_id, project_id, run_id, payload, computed_at FROM derived_outputs WHERE kind = 'analysis-report.json';
